import React from 'react';
import { Link } from 'react-router-dom';
import './Hero.css';

function Home() {
  const categories = [
    { name: 'Men\'s Clothing', img: 'https://images.unsplash.com/photo-1617137984095-74e4e5e3613f?w=200', path: '/products?category=fashion' },
    { name: 'Women\'s Clothing', img: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200', path: '/products?category=fashion' },
    { name: 'Footwear', img: 'https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=200', path: '/products?category=footwear' },
    { name: 'Jewellery', img: 'https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?w=200', path: '/products?category=jewellery' },
    { name: 'Electronics', img: 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=200', path: '/products?category=electronics' },
    { name: 'Home & Kitchen', img: 'https://images.unsplash.com/photo-1583847268964-b28dc8f51f92?w=200', path: '/products?category=home' },
  ];

  return (
    <div className="home-page">
      {/* Horizontal Category Circles Bar */}
      <div className="home-categories-wrapper">
        <div className="home-categories-track">
          {categories.map((cat, index) => (
            <Link to={cat.path} key={index} className="category-circle-card">
              <div className="circle-image-box">
                <img src={cat.img} alt={cat.name} />
              </div>
              <span>{cat.name}</span>
            </Link>
          ))}
        </div>
      </div>

      {/* Hero Promotional Banner */}
      <div className="home-hero-banner">
        <div className="hero-banner-content">
          <span className="hero-badge">Great Indian Festival</span>
          <h1>Under ₹499</h1>
          <h2>Kids' Clothing & Essentials</h2>
          <p>Explore trendsetting styles designed for comfort and durability.</p>
          <Link to="/products" className="hero-shop-btn">Shop Now</Link>
        </div>
        <div className="hero-banner-image">
          <img 
            src="https://images.unsplash.com/photo-1503944583220-7eeec3900d0d?w=600" 
            alt="Kids Clothing Promo" 
          />
        </div>
      </div>
    </div>
  );
}

export default Home;
